INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','蝴蝶泉的传说','4-5','白族少女金花在蝴蝶泉边与情人相会，化作翩翩彩蝶的美好传说，善良与忠贞的化身。','水彩手绘儿童绘本风，苍山洱海背景，泉边成群的彩色蝴蝶围绕白族小姑娘金花，蓝白扎染色调，画面温暖清新','[{"domain": "社会", "goal": "感受美好情感与善良品质"}, {"domain": "艺术", "goal": "欣赏自然之美"}]','["#白族故事", "#蝴蝶泉", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','瓦猫护家园','5-6','白族人家屋顶上的瓦猫守夜护宅、吓退邪祟的民间传说，勇敢担当。','童趣扁平插画风，白族青瓦白墙民居屋顶，一只咧嘴瓦猫精神抖擞蹲坐，月色星空下守护村庄，暖黄色灯光','[{"domain": "社会", "goal": "培养勇敢与责任心"}, {"domain": "语言", "goal": "复述传说"}]','["#白族故事", "#瓦猫", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','望夫云的传说','5-6','苍山之巅升起一朵奇云，白族公主化作望夫云，盼海底的丈夫归来，悲欢动人。','水彩写意风，苍山十九峰之巅一朵洁白长发般的云，下方洱海波涛翻涌，云影倒映水面，青蓝与月白相间','[{"domain": "社会", "goal": "理解思念与坚守"}, {"domain": "艺术", "goal": "感受自然意象之美"}]','["#白族故事", "#望夫云", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','蛇骨塔的故事','5-6','白族青年段赤诚勇斩洱海巨蟒，百姓以蛇骨建塔纪念英雄，舍己为人。','连环画叙事风，洱海畔白衣青年手持长剑与巨蟒搏斗，远处工匠垒砖砌塔，赭石与墨绿配色，气势壮阔','[{"domain": "社会", "goal": "学习舍己为人"}, {"domain": "语言", "goal": "讲述英雄事迹"}]','["#白族故事", "#蛇骨塔", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','小黄莺学艺','4-5','白族山林里的小黄莺向云雀学唱歌、向老鹰学飞翔，明白坚持才能学会本领。','明亮水彩风，苍山松林间一只金黄小鸟扑棱翅膀，周围站着云雀、老鹰等老师，嫩绿与鹅黄色调','[{"domain": "科学", "goal": "了解动物习性"}, {"domain": "社会", "goal": "懂得坚持"}]','["#白族故事", "#小黄莺", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','神鸟白鹭','3-4','洱海边上一只受伤的白鹭被白族小阿鹏救起，伤愈后年年归来陪伴孩子。','柔和水彩风，洱海边芦苇丛，白族小男孩轻轻捧起一只白羽白鹭，水面波光粼粼，浅蓝与米白','[{"domain": "社会", "goal": "爱护小动物"}, {"domain": "科学", "goal": "认识水鸟"}]','["#白族故事", "#白鹭", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','白石本主','4-5','一块有灵性的白石被白族村子尊为本主，风雨天守护庄稼丰收。','古朴壁画风，村头大青树下供着一块带花纹的白石，村民们捧来供果，青灰与土黄，庄重温暖','[{"domain": "社会", "goal": "了解本主信仰"}, {"domain": "艺术", "goal": "感受民间信仰"}]','["#白族故事", "#本主", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','金鸡报晓','4-5','白族山村的大公鸡每天清晨准时打鸣，叫醒整个村寨开始新一天的劳作。','晨雾水彩风，青瓦白墙的白族村寨上空一只红冠金鸡展翅啼鸣，炊烟袅袅，粉橙晨曦','[{"domain": "科学", "goal": "认识家禽习性"}, {"domain": "社会", "goal": "勤劳作息"}]','["#白族故事", "#金鸡", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','龙女牧羊','5-6','洱海龙王之女化作牧羊姑娘，与白族少年相知相助，善良好报的民间故事。','梦幻水彩风，苍山脚下绿草坡上，白衣龙女与白族少年并肩牧羊，羊群如云，远处洱海碧蓝，紫粉霞光','[{"domain": "社会", "goal": "懂得善良有回报"}, {"domain": "艺术", "goal": "想象神话场景"}]','["#白族故事", "#龙女", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('民间故事','百鸟朝凤','4-5','白族传说凤凰带来春天和吉祥，百鸟从苍山洱海飞来向凤凰朝拜。','工笔重彩风，山茶花开的枝头立着一只华美金凤，周围百鸟环绕，红金与翠绿，喜庆华丽','[{"domain": "艺术", "goal": "欣赏传统图案"}, {"domain": "社会", "goal": "向往美好"}]','["#白族故事", "#凤凰", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','白族扎染','4-5','以板蓝根染布、扎结成花染出蓝白纹样的传统技艺，孩子们学习图案与环保草木染。','手绘水彩风，白族奶奶和小女孩一起用扎布扎染、浸入蓝靛染缸，展开后呈现蓝底白花的扎染布，古朴雅致','[{"domain": "艺术", "goal": "感受蓝白美与纹样"}, {"domain": "科学", "goal": "认识植物染料"}]','["#白族非遗", "#扎染", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','甲马版画','5-6','白族民间木刻版画甲马，印出吉祥纹样与神话形象，承载祝福与信仰。','木刻版画肌理风，白族老人手持刻刀与印版，印出红纸上生动的甲马神像图案，颜料朱红与墨黑，传统质朴','[{"domain": "艺术", "goal": "了解版画工艺"}, {"domain": "社会", "goal": "认识民间信仰与祝福"}]','["#白族非遗", "#甲马", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','剑川木雕','5-6','剑川白族木雕千年传承，花鸟鱼虫、人物故事在木头上栩栩如生。','工笔写实风，老木匠在工坊里雕琢一扇花鸟木门，木屑纷飞，身旁摆着刻好的龙凤浮雕，深棕与米黄','[{"domain": "艺术", "goal": "感受木雕工艺"}, {"domain": "社会", "goal": "尊重匠人与传承"}]','["#白族非遗", "#木雕", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','白族刺绣','4-5','白族妇女在包头、鞋头、围腰上绣上茶花、蝴蝶、孔雀，针脚细密色彩鲜艳。','细腻水彩风，白族阿姨坐在照壁下穿针引线，绣绷上一朵红山茶，彩线挂了一桌，暖粉与翠绿','[{"domain": "艺术", "goal": "欣赏刺绣纹样"}, {"domain": "社会", "goal": "了解女性巧手"}]','["#白族非遗", "#刺绣", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','鹤庆银器','5-6','鹤庆新华村白族匠人千锤百炼，打制银壶、银手镯，银光闪闪。','金属质感风，小锤敲打着通红的银坯，旁边一把亮银茶壶刻着龙凤纹，银白与炉火橙红','[{"domain": "科学", "goal": "认识金属工艺"}, {"domain": "艺术", "goal": "欣赏金银器"}]','["#白族非遗", "#银器", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','三道茶','4-5','白族待客三道茶，一苦、二甜、三回味，蕴含人生哲理。','温馨水彩风，白族木桌上摆着小陶杯，第一道清茶微苦，第二道加红糖乳扇，第三道加花椒桂皮，棕黄与木色','[{"domain": "社会", "goal": "学习待客礼仪"}, {"domain": "健康", "goal": "了解茶文化"}]','["#白族非遗", "#三道茶", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','白族剪纸','3-4','春节时白族奶奶剪出窗花和喜字，贴在白族窗棂上增添喜庆。','大红剪纸风，一双布满皱纹的手正剪一朵牡丹窗花，白墙花窗上贴着红喜字与蝴蝶，正红与雪白','[{"domain": "艺术", "goal": "欣赏剪纸艺术"}, {"domain": "社会", "goal": "感受节日喜庆"}]','["#白族非遗", "#剪纸", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','大理草帽','3-4','白族妇女用麦草编织草帽，夏天遮阳又透气，赶集时人人戴一顶。','明亮水彩风，奶奶坐在巷口编织麦草草帽，旁边摆着编好的黄草帽，金花姐姐戴上一顶去赶集，麦黄与天蓝','[{"domain": "科学", "goal": "认识植物编织"}, {"domain": "社会", "goal": "了解日常用品"}]','["#白族非遗", "#草帽", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','大理石画','5-6','苍山天然大理石剖开后纹理如山水，白族匠人将其制成屏画，天然成趣。','清雅水墨风，匠人缓缓掀开一块大理石板，石面天然浮现苍山云海图，石青与灰白，配木框','[{"domain": "科学", "goal": "认识岩石纹理"}, {"domain": "艺术", "goal": "欣赏天然之美"}]','["#白族非遗", "#大理石画", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('非遗工艺','周城扎染作坊','4-5','周城村家家染布，蓝布在风中飘成一片片蓝色的云。','清新水彩风，白族院子里竹竿上挂满随风飘动的蓝白扎染布，小女孩仰头看蓝布如天空，靛蓝与木色','[{"domain": "社会", "goal": "了解扎染之乡"}, {"domain": "艺术", "goal": "感受蓝白韵律"}]','["#白族非遗", "#周城", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','三坊一照壁','4-5','白族传统民居布局：三面房屋围合成坊、正对面照壁，青瓦白墙彩绘，天人合一的居住智慧。','明亮彩铅风，白族庭院全景，三坊房屋围合、洁白照壁上绘吉祥花鸟，院中天井开满山茶花，蓝天白云','[{"domain": "科学", "goal": "认识建筑格局"}, {"domain": "社会", "goal": "了解家乡民居"}]','["#白族民居", "#建筑", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','崇圣寺三塔','3-4','大理标志性的三座古塔，耸立在苍山洱海之间，千百年来守护着大理。','可爱卡通风，苍山洱海前三座白塔高低错落，云朵和飞鸟相伴，色彩明快柔和，适合低幼欣赏','[{"domain": "社会", "goal": "认识家乡地标"}, {"domain": "艺术", "goal": "欣赏古建筑之美"}]','["#白族地标", "#三塔", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','喜洲古镇','4-5','喜洲白族民居建筑群，青瓦白墙、门楼雕花，石板路上马蹄声远去。','古街水彩风，青石板路两旁是白族民居，门楼飞檐雕花，游客三三两两，远山含黛，灰瓦与雪白','[{"domain": "社会", "goal": "了解古镇历史"}, {"domain": "艺术", "goal": "欣赏民居彩绘"}]','["#白族民居", "#喜洲", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','本主庙','5-6','每个白族村寨都有一座本主庙，供奉本村保护神，红墙青瓦香火不绝。','庄重壁画风，古树下一座红墙庙宇，屋脊上蹲一排小瓦猫，村民捧香参拜，朱红与墨绿','[{"domain": "社会", "goal": "了解本主文化"}, {"domain": "艺术", "goal": "欣赏庙宇建筑"}]','["#白族建筑", "#本主庙", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','洱海渔船','3-4','白族渔民划着小木船在洱海上收网，海鸥跟着船飞。','童趣水彩风，湛蓝洱海上一叶小木船，渔民撒网，几只白鸥绕船飞，远山如黛，湖蓝与木棕','[{"domain": "科学", "goal": "认识渔民生活"}, {"domain": "社会", "goal": "了解洱海生态"}]','["#白族生活", "#渔船", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','凤阳驿','4-5','茶马古道上的白族驿站，马帮铃声叮当当，驮来茶叶和盐巴。','怀旧水彩风，古驿站门口拴着一队驮马，马锅头在喝大碗茶，灯笼高挂，暖黄与土褐','[{"domain": "社会", "goal": "了解茶马古道"}, {"domain": "历史", "goal": "认识马帮文化"}]','["#白族古道", "#驿站", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','五华楼','5-6','大理古城中心的五华楼，城楼高耸，登楼可俯瞰整座古城。','透视建筑风，重檐歇山顶的古城楼巍峨耸立，楼下石板街行人如织，远处苍山，金顶与青灰','[{"domain": "社会", "goal": "认识古城地标"}, {"domain": "艺术", "goal": "欣赏城楼形制"}]','["#白族建筑", "#五华楼", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','白族天井','4-5','白族民居天井里养花、种茶花、养一缸鱼，下雨天雨水滴进缸里叫\'聚财\'。','细腻水彩风，四方天井中央一口大缸养着红鱼，四周摆满山茶与兰花，青瓦屋檐滴水，淡绿与瓷青','[{"domain": "科学", "goal": "观察植物与鱼"}, {"domain": "社会", "goal": "了解居住智慧"}]','["#白族民居", "#天井", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','洱海门','3-4','大理古城东门洱海门，清晨从这里出城，就能看到广阔的洱海。','晨光卡通风，古老城门口背着小书包的金花妹妹向外跑，门外洱海金光粼粼，橙红与天蓝','[{"domain": "社会", "goal": "认识古城城门"}, {"domain": "健康", "goal": "早起晨练"}]','["#白族地标", "#洱海门", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('建筑场景','石门关','5-6','苍山石门关两岸石壁对峙，一条江水从关下穿过，险峻壮观。','壮阔水彩风，两侧刀削般青灰石壁夹着碧绿江水，栈道悬空，一只苍鹰盘旋，石青与墨绿','[{"domain": "科学", "goal": "认识峡谷地貌"}, {"domain": "社会", "goal": "欣赏家乡山河"}]','["#白族地标", "#石门关", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','金花姐姐','3-4','勤劳美丽的白族少女形象，头戴凤冠、身披彩带，是善良与美的化身。','童趣水彩风，白族小姑娘金花头戴白色凤冠帽、坠彩带，穿着白族红蓝绣花服饰，笑容亲切，站在花丛中','[{"domain": "社会", "goal": "感受真善美"}, {"domain": "艺术", "goal": "欣赏民族服饰"}]','["#白族人物", "#金花", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','阿鹏哥哥','4-5','机智勇敢的白族青年形象，佩戴头巾、身背三弦琴，乐于助人。','手绘插画风，白族青年阿鹏缠白头巾、身着白族男装，怀抱三弦琴，在苍山洱海边弹唱，阳光俊朗','[{"domain": "社会", "goal": "学习勇敢助人"}, {"domain": "艺术", "goal": "认识民族乐器"}]','["#白族人物", "#阿鹏", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','小阿鹏','3-4','天真活泼的白族小男孩，戴虎头帽，追着蜻蜓跑，笑声朗朗。','圆润卡通风，虎头帽小男孩光脚在田埂上追一只红蜻蜓，背上小背篓，嫩绿与赭黄','[{"domain": "社会", "goal": "感受童真"}, {"domain": "健康", "goal": "亲近自然"}]','["#白族人物", "#小男孩", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','小金花','3-4','扎小辫、穿粉红围腰的白族小姑娘，蹲在地上看蚂蚁搬家。','柔和卡通风，两条小辫的白族小女孩蹲在青石板边，手指着地上一队蚂蚁，旁边一只蝴蝶飞过，粉与天蓝','[{"domain": "科学", "goal": "观察小昆虫"}, {"domain": "社会", "goal": "培养好奇心"}]','["#白族人物", "#小女孩", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','扎染奶奶','4-5','白发苍苍的白族老奶奶，手指灵巧，带着孙女一块扎染花布。','温暖水彩风，老祖母戴着老花镜坐在小院里，和小女孩一起给白布打结，桌上摆着蓝靛染缸，暖棕与靛蓝','[{"domain": "社会", "goal": "尊重长辈"}, {"domain": "艺术", "goal": "祖孙共做手工"}]','["#白族人物", "#奶奶", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','木匠爷爷','5-6','剑川老木匠，满手老茧，能把一块木头雕成会笑的小瓦猫。','写实暖画风，白胡子老木匠在工坊里刨木头，木屑卷成花，墙上挂着雕花样品，木色与阳光金','[{"domain": "社会", "goal": "学习匠人精神"}, {"domain": "艺术", "goal": "感受工艺之美"}]','["#白族人物", "#木匠", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','渔伯伯','4-5','洱海边的白族老渔民，皮肤黝黑，会撒网、会唱海菜腔。','海风吹拂风，戴麦秸草帽的伯伯站在木船头撒出一张圆网，海鸥追逐，海蓝与麦黄','[{"domain": "社会", "goal": "了解渔民生活"}, {"domain": "语言", "goal": "学唱渔歌"}]','["#白族人物", "#渔民", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','茶婆婆','3-4','笑容慈祥的白族婆婆，端出三道茶招待小客人，一苦二甜三回味。','温馨卡通风，银发婆婆系蓝围裙，手捧小茶碗递给小朋友，桌上摆着乳扇、红糖与烤茶，暖橙与木色','[{"domain": "社会", "goal": "学习待客之道"}, {"domain": "健康", "goal": "了解饮茶"}]','["#白族人物", "#茶婆", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','小阿鹏上学去','4-5','背着小书包、戴着白族帽子的小男孩走在上学路上，经过三塔。','清晨水彩风，小阿鹏背着布书包走过田野，远处三塔在晨光中，背上水壶晃悠，新绿与金黄','[{"domain": "社会", "goal": "养成上学习惯"}, {"domain": "健康", "goal": "步行锻炼"}]','["#白族人物", "#上学", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('人物角色','本主爷爷','5-6','传说里白族村寨的保护神，白胡子、持宝剑，笑眯眯守护庄稼。','传统神像风，慈祥的白须爷爷穿铠甲披红袍，一手抚须一手持剑，身后祥云缭绕，朱红与金','[{"domain": "社会", "goal": "了解保护神传说"}, {"domain": "艺术", "goal": "欣赏神像画"}]','["#白族人物", "#本主", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','火把节','4-5','农历六月二十五，白族村寨点起火把、绕田驱虫、祈福丰收的盛大节日。','热烈水彩风，白族村寨夜幕下人们高举燃烧火把绕田游行，火光映红笑脸，漫天繁星，喜庆热闹','[{"domain": "社会", "goal": "了解传统节日"}, {"domain": "健康", "goal": "感受集体欢庆"}]','["#白族节日", "#火把节", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','三月街','5-6','大理三月街，白族一年一度赶集盛会，赛马、歌舞、商贸，热闹非凡。','热闹透视插画风，大理古城外三月街集市，赛马奔腾、白族姑娘歌舞、摊位琳琅满目，人流如织色彩缤纷','[{"domain": "社会", "goal": "认识传统集市文化"}, {"domain": "语言", "goal": "讲述见闻"}]','["#白族节日", "#三月街", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','绕三灵','5-6','白族古老的歌舞盛会，人们手持柳枝、串着钱，沿着神都、圣源寺、洱河祠边走边唱。','欢腾长卷风，成百上千白族男女扎绿包头、持柳树枝，排成队伍边走边舞，鼓乐齐鸣，翠绿与红彩','[{"domain": "社会", "goal": "了解白族歌会"}, {"domain": "艺术", "goal": "欣赏集体舞"}]','["#白族节日", "#绕三灵", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','石宝山歌会','5-6','七月石宝山上，青年男女弹着龙头三弦对调子，寻找心上人。','浪漫水彩风，石宝山顶松荫下，白族青年男女围成圈对歌，三弦伴奏，落花飘落，山紫与松绿','[{"domain": "社会", "goal": "了解对歌习俗"}, {"domain": "艺术", "goal": "感受情歌文化"}]','["#白族节日", "#石宝山", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','本主节','4-5','白族村寨把本主像从庙里请出来巡游，挨家挨户祈福，锣鼓喧天。','喜庆民俗风，四人抬着红漆神轿走在青石板路上，村民举彩旗敲锣打鼓，鞭炮纸屑飞舞，朱红与金黄','[{"domain": "社会", "goal": "了解村寨节日"}, {"domain": "艺术", "goal": "欣赏巡游队伍"}]','["#白族节日", "#本主节", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','耍海会','4-5','洱海边上龙舟竞渡，白族青年划着长船在水面飞驰，岸上万人助威。','动感水彩风，洱海上十几条龙舟齐发，划船手喊着号子，龙头雕刻精美，岸上彩旗招展，湖蓝与朱砂','[{"domain": "社会", "goal": "了解龙舟习俗"}, {"domain": "健康", "goal": "感受集体运动"}]','["#白族节日", "#耍海会", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','花朝节','4-5','二月百花开，白族姑娘戴花穿城，把茶花、杜鹃花插满发髻。','明媚水彩风，青石板街上白族姑娘发髻上插满红山茶和粉杜鹃，手中提花篮，落英缤纷，粉白与翠绿','[{"domain": "艺术", "goal": "欣赏花卉之美"}, {"domain": "社会", "goal": "感受花季民俗"}]','["#白族节日", "#花朝节", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','春节打粑粑','3-4','过年时白族全家围坐石臼前，用木槌捶打糯米粑粑，越打越香。','温馨红年画风，一家人围着大石臼，大人举木槌捶糯米，小娃娃伸手要捏粑粑，红灯笼高挂，正红与米白','[{"domain": "社会", "goal": "了解年俗"}, {"domain": "健康", "goal": "品尝糯米食品"}]','["#白族节日", "#打粑粑", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','掐新娘','5-6','白族婚礼上，亲朋好友纷纷轻轻掐新娘一下，沾喜气、祝美满，热闹风趣。','诙谐喜庆风，穿大红嫁衣的新娘盖头下笑弯了腰，身旁亲友笑着轻掐她衣袖，鼓乐队在后，大红与青绿','[{"domain": "社会", "goal": "了解婚俗"}, {"domain": "语言", "goal": "讲述婚礼见闻"}]','["#白族节日", "#婚礼", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('节日民俗','尝新节','3-4','稻谷新熟，白族人家煮上新米饭先敬祖先和狗，再全家尝新。','金黄丰收风，小院木桌上摆着一碗碗新米白饭，旁边一盘煮新豆，孩子捧碗闻香，稻黄与木棕','[{"domain": "社会", "goal": "懂得珍惜粮食"}, {"domain": "科学", "goal": "认识作物成熟"}]','["#白族节日", "#尝新节", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','月亮婆婆','3-4','白族经典童谣，用朗朗上口的语言描写月夜与家乡的美好。','梦幻水彩风，夜晚白族村庄，月亮婆婆慈祥微笑挂在天边，白族孩子坐在院子里数星星，蓝紫温柔色调','[{"domain": "语言", "goal": "感受韵律与节奏"}, {"domain": "社会", "goal": "热爱家乡"}]','["#白族童谣", "#儿歌", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','苍山谣','4-5','童谣唱苍山十九峰，峰峰插云端，雪水流下来浇田又浇花。','青绿水彩风，十九座山峰连绵入云，雪水汇成小溪流下田坝，孩子放牛在山坡，天蓝与雪白','[{"domain": "语言", "goal": "学念童谣"}, {"domain": "科学", "goal": "认识雪山与溪流"}]','["#白族童谣", "#苍山", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','海菜腔','5-6','白族海菜腔山歌调子高亢悠长，像海菜在水里随风摇摆。','声乐意境风，洱海边白族大哥站在船头引吭高歌，歌声化作飘带绕山梁，海鸥驻足，湖蓝与金橙','[{"domain": "艺术", "goal": "欣赏民歌"}, {"domain": "语言", "goal": "感受长调韵律"}]','["#白族童谣", "#海菜腔", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','小白花','3-4','童谣唱墙角那朵小白花，风吹不谢、雨打不落，坚强又可爱。','柔和卡通风，青墙角一朵五瓣小白花轻轻摇晃，小瓢虫停在花瓣上，孩子蹲下来看，嫩绿与纯白','[{"domain": "科学", "goal": "观察植物"}, {"domain": "语言", "goal": "念诵短句"}]','["#白族童谣", "#小花", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','赶三月街','4-5','童谣唱阿婆背小孙赶三月街，买了彩线又买花，一路笑哈哈。','热闹水彩风，白族老奶奶背着小孙孙走在集市上，手里举着一串糖葫芦，孩子张着嘴笑，红彩与暖黄','[{"domain": "社会", "goal": "了解集市"}, {"domain": "语言", "goal": "学念童谣"}]','["#白族童谣", "#三月街", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','扎染歌','4-5','儿歌教小朋友一块白布折三折、扎四扎，泡进蓝缸变梅花。','童趣步骤风，四格小图：折布—扎结—染缸—展开蓝花，像连环画，靛蓝与米白','[{"domain": "艺术", "goal": "学做扎染"}, {"domain": "语言", "goal": "念唱步骤"}]','["#白族童谣", "#扎染", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','蝴蝶泉边','4-5','童谣唱蝴蝶泉边蝴蝶飞，金花姐姐在泉边洗彩裙。','清新水彩风，蝴蝶泉边树下落满蝴蝶，金花姐姐蹲在泉边漂洗蓝裙，水面倒影如花，碧绿与天蓝','[{"domain": "语言", "goal": "感受韵律"}, {"domain": "艺术", "goal": "欣赏画面"}]','["#白族童谣", "#蝴蝶泉", "#中班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','小螃蟹','3-4','童谣唱洱海边小螃蟹横着走，举起大钳子像拜拜。','圆润卡通风，洱海边礁石上一只红壳小螃蟹举着双钳，小朋友拍手笑，海浪轻柔，珊瑚红与海蓝','[{"domain": "科学", "goal": "认识小螃蟹"}, {"domain": "语言", "goal": "学拟声词"}]','["#白族童谣", "#小螃蟹", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','星星点灯','3-4','童谣唱满天星斗像白族奶奶缝衣时落下的银针。','梦幻深蓝风，洒满繁星的夜空下，奶奶坐在院里油灯下穿针，孩子依偎身旁，深蓝与暖黄','[{"domain": "语言", "goal": "感受比喻"}, {"domain": "社会", "goal": "祖孙温情"}]','["#白族童谣", "#星星", "#小班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
INSERT INTO materials (material_type,name,age_band,description,image_prompt,edu_goals,tags,status) VALUES ('童谣儿歌','绣花曲','5-6','白族绣花调，阿妹坐在花架前，一针一线绣出百鸟朝凤。','工笔柔美风，白族阿妹低头在绣绷上绣金凤凰，彩线如彩虹绕指，窗台上摆着山茶，樱粉与翠绿','[{"domain": "艺术", "goal": "欣赏刺绣"}, {"domain": "语言", "goal": "学唱小调"}]','["#白族童谣", "#绣花", "#大班绘本"]','published') ON DUPLICATE KEY UPDATE material_type=VALUES(material_type), age_band=VALUES(age_band), description=VALUES(description), image_prompt=VALUES(image_prompt), edu_goals=VALUES(edu_goals), tags=VALUES(tags);
